"""Anonymous, post-seal CPU diagnosis export; no inference or optimizer calls."""
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.diagnose_stvg_temporal_b256_v1 import BASE,B,read,write,sha
OUT=ROOT/'results/stvg_temporal_hypothesis/2026-10-17/diagnosis256'
CONTRASTS={'Projection_minus_Frozen','T2_minus_Projection','T2_minus_Frozen','T2_reward_view_minus_Projection','T2_target_view_minus_Projection','B_reward_view_minus_Frozen','B_target_view_minus_Frozen','B_minus_Frozen','B_minus_T2','B_minus_B_reward_view','B_minus_B_target_view'}
def main():
    from scripts.export_stvg_lite_batch001 import public_source_text
    from scripts.publish_stvg_soft_ep_v1 import verify_privacy
    a=read(BASE/'INDEPENDENT_READBACK.json');assert a['status']=='pass' and a['count']==256
    d=read(BASE/'RESULTS.json');p=read(BASE/'native_marginal_probe001/RESULTS.json');s=read(BASE/'OBSERVABILITY_AUDIT.json')
    assert a['diagnosis_sha256']==sha(BASE/'RESULTS.json') and a['probe_sha256']==sha(BASE/'native_marginal_probe001/RESULTS.json')
    rr=read(B/'ROSTER_LOCK.json')['records'];aliases={r['probe_alias']:f'R{i:03d}'for i,r in enumerate(rr,1)}
    def anon(x):
        if isinstance(x,dict):return {aliases.get(k,k):anon(v)for k,v in x.items()if k!='GT_bindings'}
        if isinstance(x,list):return [anon(v)for v in x]
        return aliases.get(x,x)if isinstance(x,str)else x
    OUT.mkdir(parents=True,exist_ok=False);d['paired']=[x for x in d['paired']if x['comparison']in CONTRASTS]
    write(OUT/'RESULTS.json',anon(d));write(OUT/'OBSERVABILITY_AUDIT.json',anon(s));write(OUT/'NATIVE_MARGINAL_PROBE.json',anon(p));write(OUT/'ROOT_SCALAR_READBACK.json',a)
    write(OUT/'SOURCE_BINDINGS.json',dict(count=256,records=[dict(case_id=aliases[r['probe_alias']],dataset=r['dataset'],parent_sha256=r['parent_sha256'],query_key_sha256=r['query_key_sha256'],source_checkpoint_sha256=r['source_checkpoint_sha256'])for r in rr],same_original_exposed_development256=True))
    write(OUT/'ACTUAL_SCOPE.json',dict(status='complete_CPU_diagnosis',count=256,per_domain=128,source='same cross-domain TA-STVG snapshots as original B/T2',new_models=0,new_Teacher_calls=0,new_Student_fits=0,new_GPU_jobs=0,new_video_decodes=0,GT_read=True,previously_exposed_GT_after_prediction_roots_only=True,no_Caption_Query_or_GT_coordinates_exported=True,CURRENT_changed=False,PAPER_changed=False,independent_confirmation=False,probe_is_new_parameter_free_CPU_readout_not_fitted_B=True,Projection='original normalized Actionness cost plus 0.1 Native log-prior; not Actionness-alone intervention',T2_residual='joint Teacher plus Student change conditional on Projection, not pure Teacher causal effect',B_optimization='saved zero-init512 LBFGS50/Armijo; candidate KL plus Native-grid trust; no optimizer rerun',old_T2_difference='projected full-grid base, averaged per-offset candidate score and candidate-KL multiplier2; B uses Native full-grid base, summed joint-state candidate score and multiplier1; not an isolated I2 replacement',preflight_recovery='initial CPU index read used array-files instead of source-jobs; assertion failed before GT or models; original failure/source retained, only schema corrected',oracle='metricwise fixed-pair hard-selection diagnostic; not deployable and not a free-grid Student upper bound',semantic_review='reward agreement with GT interval ordering is geometric; no new identity or role labels',all_public_rows_retained=True,public_paired_contrasts='11 selected contrasts; all arm rows retained for arbitrary reconstruction'))
    write(OUT/'COST.json',dict(new_models=0,new_GPU_jobs=0,new_Teacher_calls=0,new_Student_fits=0,new_video_decodes=0,postseal_CPU_metric_readouts=True,original_B_T2_costs_not_relabelled_zero=True,independent_CDF_probability_checks=256,probability_bins=a['independent_probability_bins']))
    def mean(dataset,arm,metric='m_vIoU',data=d):return next(z['mean']for z in data['summary']if z['dataset']==dataset and z['arm']==arm and z['metric']==metric)
    lines=['# Why Native-only Temporal B did not retain T2 gains: original256 CPU diagnosis','','Same HC128/Vid128 exposed development parents, sealed B/T2 outputs and unchanged Source boxes. No new model load, GPU job, Teacher call, Student fit, video decode or method promotion. Previously exposed target GT is used only after original prediction roots for these post-hoc diagnostics. This is neither an independent confirmation nor a new fitted B result.','','## Matched complete-cohort readouts','','|Readout|HC vIoU %|Vid vIoU %|HC tIoU %|Vid tIoU %|','|---|---:|---:|---:|---:|']
    for arm in ['Frozen','Projection','T2_reward_view','T2_target_view','T2','B_reward_view','B_target_view','B']:
        lines.append('|'+arm+'|'+'|'.join(f'{100*mean(ds,arm,m):.6f}'for m in ['m_vIoU','m_tIoU']for ds in ['hc2','vidstg'])+'|')
    lines+=['','Reward-view chooses the higher saved numerical reward; target-view chooses the higher prior-tilted target probability. Missing, truncated or equal-information cases retain the original method base: Projection for T2, Native for B. These views are diagnostic hard readouts, not replacements for the actual trained Student.','','## Projection and the old T2 gain','','The source-wise identity is T2-Frozen = (Projection-Frozen) + (T2-Projection). Projection includes the original Actionness normalization, interval cost and 0.1 Native log-prior. It is not a clean intervention on the Actionness tensor alone. The second term jointly includes Teacher feedback and Student updates; it cannot isolate a pure Teacher causal effect.','','|Domain|Projection-Frozen vIoU pp|T2-Projection vIoU pp|','|---|---:|---:|']
    for ds in ['hc2','vidstg']:lines.append(f'|{ds}|{100*(mean(ds,"Projection")-mean(ds,"Frozen")):.6f}|{100*(mean(ds,"T2")-mean(ds,"Projection")):.6f}|')
    lines+=['','HC Projection supplies +5.296639pp; subsequent Teacher+Student changes reduce it by .615883pp. Vid gains split into +.235823pp and +.207157pp, both individually uncertain. Projection usually lengthens HC intervals: median Projection/Native duration is 1.342868, so the evidence does not support a story that it simply trims background. No conclusion that all semantic feedback is harmful follows.','','## Where B loses useful signal','','The fixed B hypotheses have median interval IoU .911213 HC / .947826 Vid and median normalized total endpoint shift .093262 / .054646. Different exact sampled frame IDs (median Jaccard .066667) do not prove different event semantics. The metricwise hard-pair vIoU oracle potential above Frozen is only +1.083200pp / +.629739pp, compared with +6.135457pp / +.864622pp for the old T2 pair. This is a support diagnostic, not an upper bound on free-grid Student adaptation.','','The reward ordering agrees with GT interval tIoU ordering for 48/105 HC and 47/92 Vid pairs with informative, non-tied values. Other cases remain tied/unknown. This is geometric ordering, not independently audited event, identity or relation correctness. Raw reward hard-selection itself does not improve Frozen on average. Increasing reward strength or relaxing trust is therefore not the first supported remedy. Thirteen queries have no information (six truncated descriptions, seven equal finite rewards; zero empty descriptions).','','## Student transfer versus optimization convergence','','Final B intervals match the current prior-tilted target hard readout on 253/256 sources (126 HC, 127 Vid); all B final intervals are inside its fixed pair. Actual B minus target hard readout is -.003936pp / -.013010pp. Median realized candidate log-odds shift is .773212 / .760359 of the requested shift; direction agrees on 123/123 HC and 119/120 Vid informative fits. The single contrary Vid reward difference is approximately 3.7e-9, so its ratio is numerically unstable.','','Candidate KL falls from .008270 to .000524 HC and .008720 to .000597 Vid. This is transfer evidence, not full convergence: most original fits hit 50 iterations; final median gradient max is 1.59e-4 / 1.25e-4, above the original 1e-10 tolerance. Student limitations may remain, but they do not explain the main HC deficit when the current target hard readout has almost the same task score. Old T2 decodes outside its observed pair on 73 HC and 69 Vid sources, illustrating its different projected full-grid path.','','## A no-Actionness probability/readout probe','','Current B retains one latent two-offset state per physical interval. That state has median only 6.648177% / 5.844341% of the total Native probability assigned to the same observable merged interval. This was an explicitly declared representative-state approximation, not a falsely claimed marginal distribution.','','A single rule was locked before new probe scores: push forward the independent offset posterior by summing probabilities of all latent states merging to the same physical interval, then choose the physical interval MAP. No model, Teacher, fitting or parameter search is involved. MAP after summation differs from merging two separately chosen MAP states. All256 probability tables were independently reconstructed with a two-dimensional CDF/inclusion-exclusion implementation; no probability was clamped.','','```text','P_N(I) = sum_{z: merge(z)=I} product_o p_N^o(z_o)','I_MAP = argmax_I P_N(I)','```','','|CPU-only readout|HC vIoU %|Vid vIoU %|HC tIoU %|Vid tIoU %|','|---|---:|---:|---:|---:|']
    lines.append('|Native merged-posterior MAP|'+'|'.join(f'{100*mean(ds,"Native_marginal_MAP_CPU",m,p):.6f}'for m in ['m_vIoU','m_tIoU']for ds in ['hc2','vidstg'])+'|')
    lines+=['','Versus Frozen: +3.293934pp HC, paired source t95 [1.845394,4.742474], 79+/25-/24neutral; +.455624pp Vid, t95 [-.133778,1.045027], 48+/32-/48neutral. Versus T2: -1.386821pp HC, t95 [-2.595696,-.177947], and +.012645pp Vid, t95 [-.335514,.360803]. These exposed-development findings are a new parameter-free CPU readout, not an improved fitted B result, independent test or established Vid gain.','','The same prelocked probability ranking supplies an alternative to the original Native interval with distinct actual uniform8 samples on all256 sources. Offline hard-pair oracle potential becomes +4.592522pp HC / +1.086232pp Vid; no new pixels, descriptions, rewards or Student predictions have been generated for this new support.','','## Next minimal discriminating test (proposal only; not launched)','','1. Keep the current Native I1, Teacher/Prompt, eight-frame budget, reward, temperature, trainable512 parameters, optimizer and Native trust unchanged. Replace only the I2 ranking by observable merged-interval Native probability; keep its representative-state training semantics explicit. This isolates support construction, without Actionness, Expand/Contract or an optimizer search.','2. Retain the measured parameter-free marginal MAP readout as a separate no-update control. Its free decoder gain must never be credited to Teacher supervision or TTA. Acquire real new-I2 visual evidence and fresh feedback before fitting; do not reuse unrelated old captions for new intervals. Seal all predictions before evaluation.','3. Report candidate support potential, numerical Teacher ordering and realized Student metrics separately. If same-Teacher ordering remains unhelpful despite improved support, evaluate a separately locked pairwise semantic comparison later; do not simultaneously alter Prompt, reward scale and optimizer.','4. A fully marginal candidate-target objective would require log-sum-exp over all states representing each interval, with corresponding gradients; it is a distinct future representation change, not a silent rescaling of the current joint-state loss.','','No new GPU experiment or rollout was launched by this diagnosis. Original negative B, failed confirmation, CURRENT/PAPER and other queues are preserved. Native posterior aggregation currently uses TA-STVG two-offset structure; cross-backbone plug-and-play has not been measured. All original source rows, signed positive/negative/neutral/unknown outcomes, implementation limitations and post-hoc data exposure are retained in the accompanying JSON.','']
    (OUT/'REPORT.md').write_text('\n'.join(lines)+'\n')
    import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
    fig,axs=plt.subplots(1,2,figsize=(12,4.5));arms=['Frozen','Projection','T2','B','Native_marginal_MAP_CPU'];labels=['Frozen','Projection','T2','B','Native marginal\nCPU no update']
    for ax,ds in zip(axs,['hc2','vidstg']):
        vals=[100*mean(ds,arm,data=p if arm=='Native_marginal_MAP_CPU'else d)for arm in arms];ax.bar(range(5),vals,color=['#999999','#b77a38','#368cbf','#a25767','#4b987b']);ax.set_xticks(range(5),labels,rotation=15,ha='right');ax.set_title(ds+' / original exposed128');ax.set_ylabel('vIoU (%)');ax.set_ylim(0,max(vals)*1.16)
        for i,v in enumerate(vals):ax.text(i,v+.06,f'{v:.3f}',ha='center',va='bottom',fontsize=9)
    fig.suptitle('Matched diagnosis; marginal CPU readout is not a fitted B result',fontsize=11);fig.tight_layout();fig.savefig(OUT/'effects.png',dpi=170);plt.close(fig)
    for name in ['diagnose_stvg_temporal_b256_v1','diagnose_stvg_temporal_b_support256_v1','probe_stvg_native_merged_posterior256_v1','audit_stvg_temporal_b_diagnosis256_v1','report_stvg_temporal_b_diagnosis256_v1']:
        dest=OUT/'code'/(name+'.py');dest.parent.mkdir(exist_ok=True);dest.write_text(public_source_text((ROOT/'scripts'/(name+'.py')).read_bytes()))
    (OUT/'PROTOCOL.md').write_text((ROOT/'protocols/stvg_temporal_b_diagnosis256_v1.md').read_text())
    write(OUT/'CPU_PROBE_LOCK.json',read(BASE/'native_marginal_probe001/LOCK.json'))
    paths=sorted(str(f.relative_to(ROOT))for f in OUT.rglob('*')if f.is_file());verify_privacy(set(paths));write(BASE/'publication/diagnosis256/EXPORT_MANIFEST.json',dict(status='complete',count=256,paths=paths,files=[dict(path=f,bytes=(ROOT/f).stat().st_size,sha256=sha(ROOT/f))for f in paths]));print('DIAGNOSIS256_EXPORT_READY',len(paths),a['scalar_checks'])
if __name__=='__main__':main()
